<script setup>
import {computed,onBeforeUnmount,ref} from 'vue';
import Icon from './Icon.vue';
import VirtualList from './VirtualList.vue';
const props=defineProps({modelValue:{default:''},options:{type:Array,default:()=>[]},placeholder:{default:'请选择'},disabled:Boolean,label:{default:'选择选项'}});
const emit=defineEmits(['update:modelValue','change']);const open=ref(false),query=ref(''),host=ref(null);
const selected=computed(()=>props.options.find(o=>String(o.value)===String(props.modelValue)));
const filtered=computed(()=>props.options.filter(o=>String(o.label).toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())));
function choose(option){if(option.disabled)return;emit('update:modelValue',option.value);emit('change',{target:{value:option.value}});open.value=false;query.value='';}
function outside(event){if(!host.value?.contains(event.target))open.value=false;}
globalThis.document?.addEventListener('pointerdown',outside);onBeforeUnmount(()=>globalThis.document?.removeEventListener('pointerdown',outside));
</script>
<template><div ref="host" class="search-select" @keydown.esc.stop="open=false"><button type="button" class="search-select-trigger" role="combobox" :aria-label="label" :aria-expanded="open" aria-haspopup="listbox" :disabled="disabled" @click="open=!open"><span>{{ selected?.label||placeholder }}</span><Icon name="down" :size="14"/></button><div v-if="open" class="search-select-menu"><input v-model="query" :aria-label="`搜索${label}`" placeholder="输入关键词搜索" @keydown.enter.prevent="filtered[0]&&choose(filtered[0])"/><VirtualList role="listbox" :items="filtered" :row-height="38" :item-key="item=>item.value" height="260px"><template #default="{item}"><button type="button" role="option" :aria-selected="String(modelValue)===String(item.value)" :disabled="item.disabled" :title="item.label" @click="choose(item)">{{ item.label }}</button></template></VirtualList><p v-if="!filtered.length">没有匹配的选项</p></div></div></template>
<style scoped>.search-select{position:relative;min-width:0;width:100%;text-align:left}.search-select-trigger{display:flex;width:100%;align-items:center;justify-content:space-between;gap:12px;border:1px solid var(--border);border-radius:9px;padding:11px 13px;min-height:42px;background:var(--surface);color:var(--text);font:inherit;text-align:left;cursor:pointer}.search-select-trigger>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.search-select-trigger:disabled{opacity:.5;cursor:default}.search-select-menu{position:absolute;top:calc(100% + 6px);left:0;min-width:260px;width:100%;z-index:60;background:var(--surface);border:1px solid var(--border);box-shadow:0 10px 35px #16152b22;border-radius:10px;overflow:hidden;padding:8px;box-sizing:border-box}.search-select-menu>input{box-sizing:border-box;width:100%;padding:10px;border:1px solid var(--border);background:var(--page);border-radius:7px;color:var(--text);margin-bottom:6px}.search-select-menu :deep([role=option]){display:block;width:100%;height:38px;padding:8px 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:0;border-radius:6px;background:transparent;color:var(--text);text-align:left;font:inherit;cursor:pointer}.search-select-menu :deep([role=option]:hover),.search-select-menu :deep([aria-selected=true]){background:var(--accent-soft);color:var(--accent)}.search-select-menu>p{font-size:12px;color:var(--muted);text-align:center}</style>
